FILES = {'config.py': '# 只修改本文件，然后重新运行 tools/build_install.py 生成 install.py。\nBUILD_ID = "FLOW_20261012_V1"\nQR_CAMERA = "ONBOARD"  # 将来只把此行改为 "USB"；颜色识别始终使用自带摄像头。\nUART_ENABLE = True\nUART_ID = 3\nUART_TX_PIN = 32  # 亚博12针排针物理第5脚，GPIO32。\nUART_RX_PIN = 33  # 亚博12针排针物理第3脚，GPIO33。\nUART_BAUD = 115200\nWIDTH, HEIGHT = 640, 480\nIDE_PREVIEW = False  # LCD始终显示。调试IDE画面时改True，会增加传输开销。\nPROCESS_SCALE = 0.25  # 仅颜色分割缩小；显示、坐标和扫码仍为640x480。\nRING_SCALE = 0.5\nDETECT_PERIOD_MS = 100  # 识别间隔；收到定位请求时立即处理新图像。\nQR_SCAN_PERIOD_MS = 150  # 扫码间隔；间隔中继续刷新LCD，确认次数按实际解码计。\nPRINT_INTERVAL_MS = 1000\nGC_INTERVAL_MS = 1000\nQR_CONFIRM_FRAMES = 3\nTASK_RETRY_MS = 1000\nMAX_RESULT_AGE_MS = 600\nACTIVE_COLOR_IDS = (1, 2, 3, 4, 5, 6)\nCOLOR_ROIS = {"RAW": (80, 60, 480, 360), "PROCESS": None,\n              "STORE": None, "STACK": None}\nDETECT_ROI = COLOR_ROIS["RAW"]\nEDGE_MARGIN = 2\nMIN_PIXELS = 32  # 在缩小后的图像中计数。真实物料仍需验证。\nMAX_AREA_FRACTION = 0.45\nMIN_DENSITY = 0.25\nMIN_ASPECT, MAX_ASPECT = 0.25, 4.0\nMORPH_RADIUS = 1\nSTABLE_FRAMES = 4\nSTABLE_DISTANCE_PX = 12\nREFERENCE_PIXEL = (320, 240)\nPLANE_H, PLANE_ROI = None, None\n# 每种实际工作高度分别标定。None表示不能输出可信毫米坐标。\nCALIBRATIONS = {"RAW": (None, None), "PROCESS": (None, None),\n                "STORE": (None, None), "STACK": (None, None)}\n# 各工位在图像中的区域必须按现场数字1/2/3建立映射，不能猜左右顺序。\nSTATION_ROIS = {"PROCESS": {}, "STORE": {}}\nRING_SLOT_ROIS = {}\nRING_THRESHOLD = 3500\nRING_MIN_RADIUS, RING_MAX_RADIUS = 8, 90  # 在RING_SCALE=0.5图像中。\nCOLOR_NAMES = {1: "RED", 2: "YELLOW", 3: "BLUE", 4: "GREEN", 5: "BLACK", 6: "LIGHT_BLUE"}\nDRAW_COLORS = {1: (255,40,40), 2: (255,255,0), 3: (80,100,255),\n               4: (0,255,0), 5: (255,255,255), 6: (0,255,255)}\nHSV_RANGES = {\n    1: ((0,10,100,255,60,255), (170,179,100,255,60,255)),\n    2: ((15,34,100,255,80,255),),\n    3: ((100,135,150,255,60,255),),\n    4: ((35,79,80,255,60,255),),\n    5: ((0,179,0,255,0,65),),\n    6: ((80,135,50,149,100,255),),\n}\n', 'vision_core.py': '# K230 port of GX silver HSV pipeline; see docs/移植说明.md.\nimport os\nimport sys\nimport time\nfrom config import *\n\ndef rgb_to_hsv(rgb, np):\n    """Vectorized RGB -> OpenCV-style HSV; works with ulab and desktop NumPy."""\n    dtype = getattr(np, "float", float)\n    r = np.array(rgb[:, :, 0], dtype=dtype)\n    g = np.array(rgb[:, :, 1], dtype=dtype)\n    b = np.array(rgb[:, :, 2], dtype=dtype)\n    v = np.maximum(np.maximum(r, g), b)\n    low = np.minimum(np.minimum(r, g), b)\n    delta = v - low\n    denominator = np.maximum(delta, 1)\n    h = np.where(v == r, (g - b) * 30 / denominator,\n                 np.where(v == g, (b - r) * 30 / denominator + 60,\n                          (r - g) * 30 / denominator + 120))\n    h = np.where(h < 0, h + 180, h)\n    h = np.where(delta == 0, 0, h)\n    s = delta * 255 / np.maximum(v, 1)\n    return h, s, v\n\n\ndef color_mask(h, s, v, ranges, np):\n    mask = np.zeros(h.shape, dtype=np.uint8)\n    for lo_h, hi_h, lo_s, hi_s, lo_v, hi_v in ranges:\n        part = (h >= lo_h) * (h <= hi_h) * (s >= lo_s) * (s <= hi_s) * (v >= lo_v) * (v <= hi_v)\n        mask = np.array(np.where(part, 255, mask), dtype=np.uint8)\n    return mask\n\n\ndef classify_position(cx, cy):\n    """Reference\'s left-up/right-up/down zones, scaled to the output image."""\n    x, y = cx - WIDTH / 2, cy - HEIGHT / 2\n    if -320 <= x <= -50 and -240 <= y <= 50:\n        return 0\n    if 50 <= x <= 320 and -240 <= y <= 50:\n        return 1\n    if -150 <= x <= 150 and 50 <= y <= 240:\n        return 2\n    # Outside configured zones stays unknown; do not invent a position.\n    return -1\n\n\ndef overlap_ratio(a, b):\n    x1, y1, w1, h1 = a\n    x2, y2, w2, h2 = b\n    shared = max(0, min(x1 + w1, x2 + w2) - max(x1, x2)) * max(0, min(y1 + h1, y2 + h2) - max(y1, y2))\n    return shared / max(1, min(w1 * h1, w2 * h2))\n\n\nclass StableTracker:\n    """记录每种目标最近几帧的位置，用于判断物料是否已经稳定。"""\n    def __init__(self):\n        self.history = {}  # {目标ID: [(cx, cy), ...]}，最多保留STABLE_FRAMES个中心点。\n\n    def update(self, records):\n        current = {}\n        for record in records:\n            key = record["id"]\n            if not record["valid"]:\n                record["stable"] = False\n                continue\n            old = self.history.get(key, [])\n            points = (old + [(record["cx"], record["cy"])])[-STABLE_FRAMES:]\n            if any(abs(x - record["cx"]) > STABLE_DISTANCE_PX or\n                   abs(y - record["cy"]) > STABLE_DISTANCE_PX for x, y in points):\n                points = [(record["cx"], record["cy"])]\n            current[key] = points\n            record["stable"] = len(points) >= STABLE_FRAMES\n        self.history = current\n\n\ndef detect_colors(frame, np, image, color_ids=None):\n    roi = DETECT_ROI or (0, 0, frame.width(), frame.height())\n    small = frame.copy(roi=roi, x_scale=PROCESS_SCALE, y_scale=PROCESS_SCALE)\n    rgb = small.to_rgb888()\n    h, s, v = rgb_to_hsv(rgb.to_numpy_ref(), np)\n    records = []\n    pw, ph = small.width(), small.height()\n    sx, sy = roi[2] / pw, roi[3] / ph\n    for color_id in (color_ids or ACTIVE_COLOR_IDS):\n        data = color_mask(h, s, v, HSV_RANGES[color_id], np)\n        mask = image.Image(pw, ph, image.GRAYSCALE, alloc=image.ALLOC_REF, data=data)\n        mask.open(MORPH_RADIUS)\n        mask.close(MORPH_RADIUS)\n        blobs = mask.find_blobs([(128, 255)], x_stride=1, y_stride=1,\n                                pixels_threshold=MIN_PIXELS, area_threshold=MIN_PIXELS,\n                                merge=False)\n        candidates = []\n        for blob in blobs:\n            x, y, w, height = blob.rect()\n            area = w * height\n            if x < EDGE_MARGIN or y < EDGE_MARGIN or x+w > pw-EDGE_MARGIN or y+height > ph-EDGE_MARGIN:\n                continue\n            aspect = w / max(1, height)\n            if area > pw * ph * MAX_AREA_FRACTION or blob.pixels() / max(1, area) < MIN_DENSITY:\n                continue\n            if not MIN_ASPECT <= aspect <= MAX_ASPECT:\n                continue\n            candidates.append(blob)\n        if not candidates:\n            continue\n        # Largest connected region per color (reference: largest external contour).\n        blob = max(candidates, key=lambda item: item.pixels())\n        x, y, w, height = blob.rect()\n        cx, cy = int(round(blob.cx() * sx))+roi[0], int(round(blob.cy() * sy))+roi[1]\n        records.append({"id": color_id, "cx": cx, "cy": cy,\n                        "rect": (int(x * sx)+roi[0], int(y * sy)+roi[1], int(w * sx), int(height * sy)),\n                        "pixels": int(blob.pixels() * sx * sy), "pos": classify_position(cx, cy),\n                        "valid": True, "stable": False})\n    for i in range(len(records)):\n        for j in range(i + 1, len(records)):\n            if overlap_ratio(records[i]["rect"], records[j]["rect"]) >= 0.5:\n                records[i]["valid"] = False\n                records[j]["valid"] = False\n    return records\n\n\ndef point_in_roi(x, y, roi):\n    return roi is not None and roi[0] <= x < roi[0] + roi[2] and roi[1] <= y < roi[1] + roi[3]\n\n\ndef plane_point(cx, cy):\n    # Never extrapolate outside the calibrated work plane.\n    if PLANE_H is None or len(PLANE_H) != 9 or not point_in_roi(cx, cy, PLANE_ROI):\n        return None\n    a, b, c, d, e, f, g, h, i = PLANE_H\n    divisor = g * cx + h * cy + i\n    if abs(divisor) < 1e-8:\n        return None\n    return ((a * cx + b * cy + c) / divisor, (d * cx + e * cy + f) / divisor)\n\n\ndef detect_rings(frame):\n    gray = frame.copy(x_scale=RING_SCALE, y_scale=RING_SCALE).to_grayscale()\n    circles = sorted(gray.find_circles(threshold=RING_THRESHOLD, x_margin=10, y_margin=10,\n                     r_margin=10, r_min=RING_MIN_RADIUS, r_max=RING_MAX_RADIUS, r_step=2),\n                     key=lambda circle: circle.magnitude(), reverse=True)\n    sx, sy = frame.width() / gray.width(), frame.height() / gray.height()\n    records = []\n    for circle in circles:\n        cx, cy = int(round(circle.x() * sx)), int(round(circle.y() * sy))\n        # Concentric score rings describe one station, not several stations.\n        if any(abs(cx - r["cx"]) < 20 and abs(cy - r["cy"]) < 20 for r in records):\n            continue\n        slots = [slot for slot, roi in RING_SLOT_ROIS.items() if point_in_roi(cx, cy, roi)]\n        slot = slots[0] if len(slots) == 1 else 0\n        radius = int(round(circle.r() * sx))\n        records.append({"id": slot, "slot": slot, "cx": cx, "cy": cy,\n                        "rect": (cx-radius, cy-radius, 2*radius, 2*radius),\n                        "radius": radius, "pixels": 0, "pos": -1,\n                        "valid": True, "stable": False})\n        if len(records) >= 3:\n            break\n    # Multiple detected centers within one configured station is ambiguous.\n    for r in records:\n        if r["slot"] and sum(other["slot"] == r["slot"] for other in records) > 1:\n            r["valid"] = False\n    return records\n\n\ndef crc16(data):\n    value = 0xFFFF\n    for byte in data:\n        value ^= byte << 8\n        for _ in range(8):\n            value = ((value << 1) ^ 0x1021) & 0xFFFF if value & 0x8000 else (value << 1) & 0xFFFF\n    return value\n\n\ndef wire_frame(seq, kind, *fields):\n    body = ",".join(["V1", str(seq), kind] + [str(value) for value in fields])\n    data = body.encode("ascii")\n    if not 0 <= seq <= 65535 or any(ch in body for ch in "$*\\r\\n") or len(data) > 240:\n        raise ValueError("Invalid protocol frame")\n    return b"$" + data + ("*%04X\\r\\n" % crc16(data)).encode("ascii")\n\n\nclass FrameParser:\n    """接收并校验STM32发来的V1 ASCII请求帧。"""\n    def __init__(self):\n        self.buffer = bytearray()  # 从字符\'$\'开始收集的当前串口帧。\n        self.errors = 0            # CRC、字符范围或帧格式错误的累计次数。\n\n    def feed(self, data):\n        frames = []\n        for byte in data:\n            if byte == 36:  # \'$\' always resynchronizes.\n                self.buffer = bytearray(b"$")\n            elif self.buffer:\n                if byte == 10:\n                    raw = bytes(self.buffer[1:]).rstrip(b"\\r")\n                    self.buffer = bytearray()\n                    try:\n                        body, checksum = raw.rsplit(b"*", 1)\n                        if len(checksum) != 4 or crc16(body) != int(checksum, 16):\n                            raise ValueError("CRC")\n                        fields = body.decode("ascii").split(",")\n                        if len(fields) < 3 or fields[0] != "V1" or not fields[1].isdigit():\n                            raise ValueError("Header")\n                        seq = int(fields[1])\n                        if seq > 65535:\n                            raise ValueError("Sequence")\n                        frames.append((seq, fields[2], fields[3:]))\n                    except (ValueError, UnicodeError):\n                        self.errors += 1\n                elif len(self.buffer) < 248 and (byte == 13 or 32 <= byte <= 126):\n                    self.buffer.append(byte)\n                else:\n                    self.buffer = bytearray()\n                    self.errors += 1\n        return frames\n\n\nclass VisionLink:\n    """K230与STM32之间的UART3通信接口。"""\n    def __init__(self):\n        self.uart = None             # UART_ENABLE为真时保存实际UART3对象。\n        self.parser = FrameParser()  # 将UART字节流解析成(seq, command, args)。\n        if UART_ENABLE:\n            if UART_ID not in (1, 2, 3, 4) or not isinstance(UART_TX_PIN, int) or not isinstance(UART_RX_PIN, int):\n                raise ValueError("Set exposed UART_ID/TX/RX before enabling UART")\n            if UART_TX_PIN == UART_RX_PIN:\n                raise ValueError("TX and RX must differ")\n            from machine import UART, FPIOA\n            fpioa = FPIOA()\n            fpioa.set_function(UART_TX_PIN, getattr(fpioa, "UART%d_TXD" % UART_ID), ie=0, oe=1)\n            fpioa.set_function(UART_RX_PIN, getattr(fpioa, "UART%d_RXD" % UART_ID), ie=1, oe=0)\n            self.uart = UART(getattr(UART, "UART%d" % UART_ID), baudrate=UART_BAUD,\n                             bits=UART.EIGHTBITS, parity=UART.PARITY_NONE, stop=UART.STOPBITS_ONE)\n            print("[GX_UART] UART%d TX=GPIO%d RX=GPIO%d BAUD=%d" % (UART_ID, UART_TX_PIN, UART_RX_PIN, UART_BAUD))\n\n    def poll(self):\n        if self.uart is None or not self.uart.any():\n            return []\n        return self.parser.feed(self.uart.read(256) or b"")\n\n    def send(self, seq, kind, *fields):\n        data = wire_frame(seq, kind, *fields)\n        if self.uart is not None:\n            sent = 0\n            while sent < len(data):\n                count = self.uart.write(data[sent:])\n                if not count:\n                    raise OSError("UART write timeout")\n                sent += count\n        return data\n\n    def close(self):\n        if self.uart is not None:\n            self.uart.deinit()\n\n\ndef hex_payload(payload):\n    data = payload.encode("utf-8")\n    if len(data) > 64:\n        return None\n    return "".join("%02X" % byte for byte in data)\n\n\ndef result_frames(seq, mode, records, marker, payload, qr_streak, now_ms):\n    """Fresh measurements only. DONE count is the number of data records."""\n    frames = []\n    if mode in ("COLOR", "RING"):\n        for r in records:\n            xy = plane_point(r["cx"], r["cy"])\n            frames.append(wire_frame(seq, "BLOCK" if mode == "COLOR" else "RING",\n                          r["id"], r["cx"], r["cy"], r["cx"]-REFERENCE_PIXEL[0], r["cy"]-REFERENCE_PIXEL[1],\n                          r["pixels"], r.get("slot", 0), int(r["valid"]), int(r["stable"]), int(xy is not None),\n                          "%.3f" % xy[0] if xy else "NA", "%.3f" % xy[1] if xy else "NA"))\n        if not any(r["valid"] for r in records):\n            frames.append(wire_frame(seq, "NO_TARGET"))\n    elif mode == "QR":\n        encoded = hex_payload(payload) if payload is not None else None\n        if encoded is not None:\n            frames.append(wire_frame(seq, "QR", int(task_valid(payload)), int(qr_streak >= 3), encoded))\n        elif payload is not None:\n            frames.append(wire_frame(seq, "ERROR", "QR_TOO_LONG"))\n        else:\n            frames.append(wire_frame(seq, "NO_QR"))\n    count = sum(1 for frame in frames if frame.split(b",")[2] in (b"BLOCK", b"RING", b"ARUCO", b"QR"))\n    frames.append(wire_frame(seq, "DONE", count, now_ms & 0xFFFFFFFF))\n    return frames\n\n\nclass CameraMux:\n    """Sequential onboard / USB acquisition. No unverified concurrent DMA."""\n    def __init__(self, sensor_class):\n        self.sensor_class = sensor_class  # K230自带摄像头的Sensor类。\n        self.sensor = None                # 已创建的自带摄像头对象。\n        self.uvc = None                   # 外接USB扫码摄像头的UVC接口对象。\n        self.source = None                # 当前启用的图像源：ONBOARD、USB或None。\n        self.prepare_onboard()\n\n    def prepare_onboard(self):\n        if self.sensor is None:\n            self.sensor = self.sensor_class()\n            self.sensor.reset()\n            self.sensor.set_framesize(width=WIDTH, height=HEIGHT)\n            self.sensor.set_pixformat(self.sensor_class.RGB565)\n            self.sensor.set_hmirror(False)\n            self.sensor.set_vflip(False)\n\n    def snapshot(self, mode):\n        target = "USB" if mode == "QR" and QR_CAMERA == "USB" else "ONBOARD"\n        if target != self.source:\n            self.stop()\n            if target == "USB":\n                from media.uvc import UVC\n                self.uvc = UVC\n                connected, info = UVC.probe()\n                if not connected:\n                    raise OSError("USB_CAMERA_ABSENT")\n                fourcc = getattr(UVC, "FOURCC_MJPEG", getattr(UVC, "FORMAT_MJPEG", None))\n                if fourcc is None:\n                    raise OSError("USB_API_UNSUPPORTED")\n                ok, actual = UVC.select_video_mode(UVC.video_mode(WIDTH, HEIGHT, fourcc, 30))\n                if not ok or not UVC.start(cvt=False):\n                    raise OSError("USB_MODE_FAILED")\n                print("[GX_USB]", info, actual)\n            else:\n                self.prepare_onboard()\n                self.sensor.run()\n            self.source = target\n            time.sleep_ms(1500)\n        frame = self.uvc.snapshot(timeout_ms=1000) if target == "USB" else self.sensor.snapshot()\n        if frame is None:\n            raise OSError("CAMERA_TIMEOUT")\n        if target == "USB":\n            frame = frame.to_rgb565()\n        if frame.width() != WIDTH or frame.height() != HEIGHT:\n            raise OSError("CAMERA_SIZE_MISMATCH")\n        return frame\n\n    def stop(self):\n        if self.uvc is not None:\n            self.uvc.stop()\n            self.uvc = None\n        if self.sensor is not None and self.source == "ONBOARD":\n            self.sensor.stop()\n        self.source = None\n\n\ndef task_valid(raw):\n    from workflow import parse_task\n    try:\n        parse_task(raw)\n        return True\n    except ValueError:\n        return False\n', 'workflow.py': '"""Pure MicroPython contest state machine; no hardware imports."""\nfrom config import QR_CONFIRM_FRAMES\n\nPHASES = ("RAW1", "PROCESS_PUT1", "PROCESS_GET1", "STORE1",\n          "RAW2", "PROCESS_PUT2", "PROCESS_GET2", "STACK2")\n\ndef parse_task(raw):\n    if not isinstance(raw, str) or len(raw) != 15:\n        raise ValueError("BAD_TASK")\n    groups = raw.split("+")\n    if len(groups) != 4 or any(len(g) != 3 for g in groups):\n        raise ValueError("BAD_TASK")\n    a, b, c, d = groups\n    if (any(ch not in "123456" for ch in a+c) or len(set(a)) != 3 or\n        sorted(a) != sorted(c) or sorted(b) != list("123") or sorted(d) != list("123")):\n        raise ValueError("BAD_TASK")\n    return tuple(tuple(int(ch) for ch in group) for group in groups)\n\ndef build_plan(raw):\n    a, b, c, d = parse_task(raw)\n    stored = dict(zip(a, b))\n    plan = []\n    for phase in PHASES:\n        second = phase.endswith("2")\n        colors, slots = (c, d) if second else (a, b)\n        for i, color in enumerate(colors):\n            if phase.startswith("RAW"):\n                mode, profile, slot, action = "COLOR", "RAW", 0, "PICK_LOAD"\n            elif phase.startswith("PROCESS_PUT"):\n                mode, profile, slot, action = "RING", "PROCESS", slots[i], "PLACE"\n            elif phase.startswith("PROCESS_GET"):\n                mode, profile, slot, action = "COLOR", "PROCESS", slots[i], "PICK_LOAD"\n            elif phase == "STORE1":\n                mode, profile, slot, action = "RING", "STORE", slots[i], "PLACE"\n            else:\n                mode, profile, slot, action = "COLOR", "STACK", stored[color], "STACK"\n            plan.append({"step":len(plan), "phase":phase, "color":color, "slot":slot,\n                         "mode":mode, "profile":profile, "action":action})\n    return plan\n\nclass Workflow:\n    def __init__(self, session=0):\n        self.session = session & 65535\n        self.raw, self.token, self.plan = None, 0, []\n        self.state, self.step = "SCAN", 0\n        self.grabs, self.places = 0, 0\n        self.previous, self.streak = None, 0\n\n    def observe(self, raw, crc):\n        if self.state != "SCAN":\n            return False\n        try:\n            parse_task(raw)\n        except ValueError:\n            self.previous, self.streak = None, 0\n            return False\n        self.streak = self.streak+1 if raw == self.previous else 1\n        self.previous = raw\n        if self.streak < QR_CONFIRM_FRAMES:\n            return False\n        self.raw, self.plan = raw, build_plan(raw)\n        self.token = (self.session << 16) | crc(raw.encode("ascii"))\n        self.state = "WAIT_ACK"\n        return True\n\n    def acknowledge(self, token):\n        if self.raw is None or token != self.token or self.state == "SCAN":\n            raise ValueError("TASK_MISMATCH")\n        if self.state == "WAIT_ACK":\n            self.state = "RUN"\n\n    def confirm_step(self, token, step):\n        if token != self.token or self.raw is None:\n            raise ValueError("TASK_MISMATCH")\n        if 0 <= step < self.step:  # Lost ACK retry: do not count the action twice.\n            return\n        if self.state != "RUN" or step != self.step or step >= len(self.plan):\n            raise ValueError("STEP_MISMATCH")\n        if self.current()["action"] == "PICK_LOAD":\n            self.grabs += 1\n        else:\n            self.places += 1\n        self.step += 1\n        if self.step == len(self.plan):\n            self.state = "RETURN_HOME"\n\n    def complete_home(self, token):\n        if token != self.token or self.state not in ("RETURN_HOME", "COMPLETE"):\n            raise ValueError("HOME_MISMATCH")\n        self.state = "COMPLETE"\n\n    def current(self):\n        return self.plan[self.step] if self.raw and self.step < len(self.plan) else None\n\n    def mode(self):\n        return self.current()["mode"] if self.state == "RUN" else "QR" if self.state == "SCAN" else "IDLE"\n\n    def reset(self):\n        self.__init__((self.session+1) & 65535)\n\n    def pause(self):\n        if self.state != "PAUSED":\n            self.before_pause = self.state\n            self.state = "PAUSED"\n\n    def resume(self):\n        if self.state == "PAUSED":\n            self.state = self.before_pause\n\n    def context(self):\n        s = self.current() or {"phase":"NONE", "color":0, "slot":0, "profile":"NONE"}\n        return (self.state, self.token, self.step, s["phase"], s["color"], s["slot"], self.mode(), s["profile"], self.grabs, self.places)\n', 'vision_app.py': '"""Scan -> reliable TASK handoff -> 24 confirmed operations, one onboard camera."""\nimport os\nimport sys\nimport time\nimport gc\nimport config as cfg\nimport vision_core as core\nfrom workflow import Workflow, parse_task\n\ndef command(work, seq, kind, args, now):\n    """Returns (response packets, needs fresh location). Pure and unit tested."""\n    def done(count=0):\n        return core.wire_frame(seq, "DONE", count, now & 0xFFFFFFFF)\n    try:\n        if kind == "TASK_ACK" and len(args) == 1:\n            work.acknowledge(int(args[0]))\n            return [core.wire_frame(seq,"ACK",work.token),done()], False\n        if kind == "STEP" and len(args) == 2:\n            token, step = int(args[0]), int(args[1])\n            work.confirm_step(token,step)\n            return [core.wire_frame(seq,"ACK_STEP",token,step),done()], False\n        if kind == "HOME_DONE" and len(args) == 1:\n            work.complete_home(int(args[0]))\n            return [core.wire_frame(seq,"ACK","HOME_DONE"),done()],False\n        if kind in ("LOCATE", "COLOR", "RING"):\n            if work.state != "RUN":\n                raise ValueError("NOT_RUNNING")\n            current = work.current()\n            if kind != "LOCATE" and kind != current["mode"]:\n                raise ValueError("WRONG_MODE")\n            if args and args != [current["profile"]]:\n                raise ValueError("BAD_PROFILE")\n            return [], True\n        if args:\n            raise ValueError("BAD_ARGS")\n        if kind == "PING":\n            return [core.wire_frame(seq,"PONG","K230","2",work.mode()),done()], False\n        if kind == "STATUS":\n            return [core.wire_frame(seq,"CONTEXT",*work.context()),done(1)], False\n        if kind == "QR":\n            return core.result_frames(seq,"QR",[],None,work.raw,3 if work.raw else 0,now),False\n        if kind == "RESET":\n            work.reset()\n        elif kind == "STOP":\n            work.pause()\n            return [core.wire_frame(seq,"STOPPED"),done()],False\n        elif kind == "RESUME":\n            work.resume()\n        else:\n            raise ValueError("BAD_COMMAND")\n        return [core.wire_frame(seq,"ACK",kind),done()],False\n    except (ValueError, TypeError, OverflowError) as exc:\n        reason=str(exc)\n        if reason not in ("TASK_MISMATCH","STEP_MISMATCH","HOME_MISMATCH","NOT_RUNNING",\n                          "WRONG_MODE","BAD_PROFILE","BAD_ARGS","BAD_COMMAND"):\n            reason="BAD_ARGS"\n        return [core.wire_frame(seq,"ERROR",reason),done()],False\n\ndef write_packet(link, data):\n    if link.uart is not None:\n        offset = 0\n        while offset < len(data):\n            count = link.uart.write(data[offset:])\n            if not count:\n                raise OSError("UART_WRITE_FAILED")\n            offset += count\n\ndef fresh_records(frame, work, tracker, np, image):\n    current = work.current()\n    profile = current["profile"]\n    core.PLANE_H, core.PLANE_ROI = cfg.CALIBRATIONS[profile]\n    core.DETECT_ROI = cfg.COLOR_ROIS[profile]\n    if current["mode"] == "COLOR":\n        task_colors = tuple(sorted(set(parse_task(work.raw)[0])))\n        records = core.detect_colors(frame,np,image,task_colors)\n    else:\n        core.RING_SLOT_ROIS = cfg.STATION_ROIS.get(profile,{})\n        if set(core.RING_SLOT_ROIS) != {1,2,3}:\n            raise ValueError("NO_SLOT_MAP")\n        records = core.detect_rings(frame)\n    tracker.update(records)\n    target = current["color"] if current["mode"] == "COLOR" else current["slot"]\n    return [r for r in records if r["id"] == target]\n\ndef main():\n    import image\n    from ulab import numpy as np\n    from media.sensor import Sensor\n    from media.display import Display\n    from media.media import MediaManager\n    camera, link = None, None\n    display_ready = media_ready = False\n    print("[FLOW_BUILD]",cfg.BUILD_ID)\n    try:\n        if cfg.QR_CAMERA not in ("ONBOARD","USB"):\n            raise ValueError("BAD_QR_CAMERA")\n        if not 0 < cfg.PROCESS_SCALE <= 1 or cfg.DETECT_PERIOD_MS < 0 or cfg.QR_SCAN_PERIOD_MS < 0:\n            raise ValueError("BAD_FRAME_SETTINGS")\n        try:\n            import urandom\n            session = urandom.getrandbits(16)\n        except ImportError:\n            session = time.ticks_ms() & 65535\n        work = Workflow(session)\n        # Initialize display before UART, so bad UART configuration is visible.\n        Display.init(Display.ST7701,width=cfg.WIDTH,height=cfg.HEIGHT,to_ide=cfg.IDE_PREVIEW)\n        display_ready = True\n        link = core.VisionLink()\n        camera = core.CameraMux(Sensor)\n        MediaManager.init()\n        media_ready = True\n        tracker = core.StableTracker()\n        frame = None\n        records = []\n        last_detect = last_report = last_gc = time.ticks_ms()\n        last_task = time.ticks_add(last_detect,-cfg.TASK_RETRY_MS)\n        last_key = None\n        frames = detections = 0\n        detect_ms = capture_ms = display_ms = 0\n        fps = detect_fps = 0.0\n        last_error = ""\n        idle_key = None\n        while True:\n            os.exitpoint()\n            pending = None\n            for seq, kind, args in link.poll():\n                if pending is not None and kind not in ("PING","STATUS"):\n                    replies = [core.wire_frame(seq,"ERROR","BUSY"),core.wire_frame(seq,"DONE",0,time.ticks_ms())]\n                    locate = False\n                else:\n                    replies, locate = command(work,seq,kind,args,time.ticks_ms())\n                for packet in replies:\n                    write_packet(link,packet)\n                if locate:\n                    pending = seq\n            now = time.ticks_ms()\n            if work.state == "WAIT_ACK" and time.ticks_diff(now,last_task) >= cfg.TASK_RETRY_MS:\n                link.send(0,"TASK",work.token,work.raw)\n                print("[FLOW_TASK] token=%s task=%s waiting=STM32_ACK" % (work.token,work.raw))\n                last_task = now\n            key = (work.state,work.step)\n            if key != last_key:\n                tracker = core.StableTracker()\n                records = []\n                last_key = key\n                last_detect = time.ticks_add(now,-cfg.DETECT_PERIOD_MS)\n                print("[FLOW_STATE]",work.context())\n            mode = work.mode()\n            if mode == "IDLE":\n                camera.stop()\n                if idle_key != key:\n                    frame = image.Image(cfg.WIDTH,cfg.HEIGHT,image.RGB565)\n                    frame.draw_string_advanced(8,10,26,cfg.BUILD_ID,color=(0,255,0))\n                    frame.draw_string_advanced(8,55,32,work.state,color=(255,255,255))\n                    frame.draw_string_advanced(8,110,32,work.raw or "WAIT TASK",color=(255,255,0))\n                    frame.draw_string_advanced(8,170,24,"GRAB %d  PLACE %d" % (work.grabs,work.places),color=(255,255,255))\n                    if work.state == "WAIT_ACK":\n                        frame.draw_string_advanced(8,210,20,"STM32 must acknowledge task",color=(255,255,255))\n                    Display.show_image(frame)\n                    idle_key = key\n                time.sleep_ms(10)\n            else:\n                idle_key = None\n                try:\n                    stamp = time.ticks_ms()\n                    frame = camera.snapshot(mode)\n                    capture_ms = time.ticks_diff(time.ticks_ms(),stamp)\n                    codes = []\n                    if mode == "QR":\n                        if time.ticks_diff(now,last_detect) >= cfg.QR_SCAN_PERIOD_MS:\n                            stamp = time.ticks_ms()\n                            codes = frame.find_qrcodes()\n                            payload = codes[0].payload() if len(codes) == 1 else None\n                            if work.observe(payload,core.crc16):\n                                last_task = time.ticks_add(time.ticks_ms(),-cfg.TASK_RETRY_MS)\n                            detect_ms = time.ticks_diff(time.ticks_ms(),stamp)\n                            last_detect = time.ticks_ms()\n                            detections += 1\n                    elif pending is not None or time.ticks_diff(now,last_detect) >= cfg.DETECT_PERIOD_MS:\n                        stamp = time.ticks_ms()\n                        records = fresh_records(frame,work,tracker,np,image)\n                        detect_ms = time.ticks_diff(time.ticks_ms(),stamp)\n                        last_detect = time.ticks_ms()\n                        detections += 1\n                        last_error = ""\n                        if pending is not None:\n                            for packet in core.result_frames(pending,mode,records,None,None,0,last_detect):\n                                write_packet(link,packet)\n                    # Cached boxes are display-only; serial results always use a fresh frame.\n                    stamp = time.ticks_ms()\n                    if mode != "QR" and time.ticks_diff(stamp,last_detect) <= cfg.MAX_RESULT_AGE_MS:\n                        for r in records:\n                            color = cfg.DRAW_COLORS.get(r["id"],(0,255,0)) if mode == "COLOR" else (0,255,0)\n                            frame.draw_rectangle(r["rect"],color=color,thickness=2)\n                            frame.draw_cross(r["cx"],r["cy"],color=color,thickness=2)\n                    for code in codes:\n                        frame.draw_rectangle(code.rect(),color=(0,255,0),thickness=2)\n                    current = work.current()\n                    title = ("%s S%d C%d P%d" % (current["phase"],work.step,current["color"],current["slot"])) if current else work.state\n                    frame.draw_string_advanced(0,0,22,title,color=(255,255,255))\n                    frame.draw_string_advanced(0,26,20,"FPS %.1f DET %.1f %s" % (fps,detect_fps,cfg.BUILD_ID),color=(255,255,0))\n                    if work.raw:\n                        frame.draw_string_advanced(0,52,24,work.raw,color=(255,255,255))\n                        frame.draw_string_advanced(0,80,20,"DONE G%d P%d" % (work.grabs,work.places),color=(0,255,0))\n                    if records and mode != "QR" and time.ticks_diff(stamp,last_detect) <= cfg.MAX_RESULT_AGE_MS:\n                        r=records[0]\n                        frame.draw_string_advanced(0,104,20,"ID %d XY %d,%d valid=%d stable=%d" %\n                            (r["id"],r["cx"],r["cy"],r["valid"],r["stable"]),color=(255,255,255))\n                    Display.show_image(frame)\n                    display_ms = time.ticks_diff(time.ticks_ms(),stamp)\n                    frames += 1\n                except Exception as exc:\n                    if "IDE interrupt" in str(exc):\n                        raise\n                    tracker = core.StableTracker()\n                    records = []\n                    if work.state == "SCAN":\n                        work.previous,work.streak = None,0\n                    reason = str(exc)[:40]\n                    if reason != last_error:\n                        print("[FLOW_FRAME_ERROR]",mode,reason)\n                        last_error = reason\n                    if pending is not None:\n                        link.send(pending,"ERROR",reason if reason == "NO_SLOT_MAP" else "VISION_FAILED")\n                        link.send(pending,"DONE",0,time.ticks_ms())\n                    error_frame = image.Image(cfg.WIDTH,cfg.HEIGHT,image.RGB565)\n                    error_frame.draw_string_advanced(0,20,24,"%s %s" % (cfg.BUILD_ID,work.state),color=(255,255,255))\n                    error_frame.draw_string_advanced(0,80,24,reason,color=(255,80,80))\n                    Display.show_image(error_frame)\n                    time.sleep_ms(20)\n            stamp = time.ticks_ms()\n            if time.ticks_diff(stamp,last_report) >= cfg.PRINT_INTERVAL_MS:\n                elapsed = max(1,time.ticks_diff(stamp,last_report))\n                fps,detect_fps = frames*1000/elapsed,detections*1000/elapsed\n                print("[FLOW_PERF] state=%s display_fps=%.1f detect_fps=%.1f capture_ms=%d detect_ms=%d draw_ms=%d" %\n                      (work.state,fps,detect_fps,capture_ms,detect_ms,display_ms))\n                if work.state == "RUN":\n                    age=time.ticks_diff(stamp,last_detect)\n                    for r in records if age <= cfg.MAX_RESULT_AGE_MS else ():\n                        print("[FLOW_TARGET] id=%d cx=%d cy=%d valid=%d stable=%d age_ms=%d" %\n                              (r["id"],r["cx"],r["cy"],r["valid"],r["stable"],age))\n                    if not records or age > cfg.MAX_RESULT_AGE_MS:\n                        print("[FLOW_NO_TARGET]")\n                frames=detections=0\n                last_report=stamp\n            if time.ticks_diff(stamp,last_gc) >= cfg.GC_INTERVAL_MS:\n                gc.collect()\n                last_gc=stamp\n    except KeyboardInterrupt:\n        print("[FLOW_STOP]")\n    except Exception as exc:\n        sys.print_exception(exc)\n        if display_ready:\n            try:\n                error_frame=image.Image(cfg.WIDTH,cfg.HEIGHT,image.RGB565)\n                error_frame.draw_string_advanced(0,20,24,"START ERROR "+cfg.BUILD_ID,color=(255,80,80))\n                error_frame.draw_string_advanced(0,75,20,str(exc)[:55],color=(255,255,255))\n                Display.show_image(error_frame)\n                while True:\n                    os.exitpoint()\n                    time.sleep_ms(50)\n            except (Exception,KeyboardInterrupt):\n                pass\n    finally:\n        for obj,method in ((link,"close"),(camera,"stop")):\n            if obj is not None:\n                try: getattr(obj,method)()\n                except Exception as exc: print("[FLOW_CLEANUP]",exc)\n        if display_ready:\n            Display.deinit()\n        if media_ready:\n            MediaManager.deinit()\n\nif __name__ == "__main__":\n    main()\n'}
LAUNCHER = '# Fixed startup entry. Install using install.py in CanMV IDE, not MTP editing.\nimport sys\nimport time\nAPP_DIR = "/sdcard/vision_current"  # install.py replaces with a verified release directory.\nsys.path.insert(0, APP_DIR)\ntime.sleep_ms(3000)\nprint("[FLOW_SOURCE]",APP_DIR)\nfor module in ("vision_app", "vision_core", "workflow", "config"):\n    if module in sys.modules:\n        del sys.modules[module]\nimport vision_app\nvision_app.main()\n'
CONFIG_KEYS = ('QR_CAMERA', 'UART_ENABLE', 'UART_ID', 'UART_TX_PIN', 'UART_RX_PIN', 'UART_BAUD', 'PROCESS_SCALE', 'IDE_PREVIEW', 'DETECT_PERIOD_MS', 'QR_SCAN_PERIOD_MS')

def exists(path):
    try:
        os.stat(path)
        return True
    except OSError:
        return False

def checked_write(path, source):
    data = source.encode("utf-8")
    with open(path,"wb") as output:
        output.write(data)
    with open(path,"rb") as stored:
        if stored.read() != data:
            raise OSError("VERIFY_FAILED:"+path)

def install(root="/sdcard"):
    if not exists(root):
        raise OSError("SD_CARD_NOT_FOUND")
    releases = root+"/vision_releases"
    backups = root+"/vision_backup"
    for directory in (releases,backups):
        if not exists(directory): os.mkdir(directory)
    number = 1
    while exists(releases+"/flow_%03d"%number): number += 1
    destination = releases+"/flow_%03d"%number
    os.mkdir(destination)
    for name,source in FILES.items():
        if name == "config.py":
            source += "\n# Overrides from install.py settings.\n"
            for key in CONFIG_KEYS:
                source += key+" = "+repr(globals()[key])+"\n"
        checked_write(destination+"/"+name,source)
    launcher = LAUNCHER.replace('APP_DIR = "/sdcard/vision_current"', 'APP_DIR = '+repr(destination))
    temporary = root+"/main.py.vision_tmp"
    checked_write(temporary,launcher)
    if hasattr(os,"sync"): os.sync()
    main = root+"/main.py"
    backup = None
    if exists(main):
        count = 1
        backup=backups+"/main.py.flow_%03d.bak"%count
        while exists(backup):
            count+=1
            backup=backups+"/main.py.flow_%03d.bak"%count
        os.rename(main,backup)
    try:
        os.rename(temporary,main)
    except Exception:
        if backup is not None and not exists(main): os.rename(backup,main)
        raise
    if hasattr(os,"sync"): os.sync()
    with open(main,"rb") as check:
        if check.read()!=launcher.encode("utf-8"): raise OSError("MAIN_VERIFY_FAILED")
    print("[INSTALL_OK]",destination)
    print("[INSTALL_OK]",main)
    print("[INSTALL_CONFIG] QR_CAMERA=%s UART=%s SCALE=%s"%(QR_CAMERA,UART_ENABLE,PROCESS_SCALE))
    print("[INSTALL_NEXT] Disconnect IDE and power-cycle. Expect [FLOW_BUILD] FLOW_20261012_V1.")

if __name__ == "__main__":
    if "k230" not in str(os.uname()).lower():
        raise RuntimeError("Run this file on K230 in CanMV IDE")
    install()
